4018	  router.patch(
4019	    "/companies/:companyId/members/:memberId",
4020	    validate(updateCompanyMemberSchema),
4021	    async (req, res) => {
4022	      const companyId = req.params.companyId as string;
4023	      const memberId = req.params.memberId as string;
4024	      await assertCompanyPermission(req, companyId, "users:manage_permissions");
4025	      const memberToUpdate = await access.getMemberById(companyId, memberId);
4026	      if (!memberToUpdate) throw notFound("Member not found");
4027	      await assertCanManageCompanyMember(req, access, companyId, memberToUpdate);
4028	
4029	      const updated = await db.transaction(async (tx) => {
4030	        await tx.execute(sql`
4031	          select ${companyMemberships.id}
4032	          from ${companyMemberships}
4033	          where ${companyMemberships.companyId} = ${companyId}
4034	            and ${companyMemberships.principalType} = 'user'
4035	            and ${companyMemberships.status} = 'active'
4036	            and ${companyMemberships.membershipRole} = 'owner'
4037	          for update
4038	        `);
4039	
4040	        const existing = await tx
4041	          .select()
4042	          .from(companyMemberships)
4043	          .where(
4044	            and(
4045	              eq(companyMemberships.companyId, companyId),
4046	              eq(companyMemberships.id, memberId),
4047	            ),
4048	          )
4049	          .then((rows) => rows[0] ?? null);
4050	        if (!existing) return null;
4051	
4052	        const nextMembershipRole =
4053	          req.body.membershipRole !== undefined
4054	            ? req.body.membershipRole
4055	            : existing.membershipRole;
4056	        const nextStatus = req.body.status ?? existing.status;
4057	
4058	        if (
4059	          existing.principalType === "user" &&
4060	          existing.status === "active" &&
4061	          existing.membershipRole === "owner" &&
4062	          (nextStatus !== "active" || nextMembershipRole !== "owner")
4063	        ) {
4064	          const activeOwnerCount = await tx
4065	            .select({ id: companyMemberships.id })
4066	            .from(companyMemberships)
4067	            .where(
4068	              and(
4069	                eq(companyMemberships.companyId, companyId),
4070	                eq(companyMemberships.principalType, "user"),
4071	                eq(companyMemberships.status, "active"),
4072	                eq(companyMemberships.membershipRole, "owner"),
4073	              ),
4074	            )
4075	            .then((rows) => rows.length);
4076	          if (activeOwnerCount <= 1) {
4077	            throw conflict("Cannot remove the last active owner");
4078	          }
4079	        }
4080	
4081	        return tx
4082	          .update(companyMemberships)
4083	          .set({
4084	            membershipRole: nextMembershipRole,
4085	            status: nextStatus,
4086	            updatedAt: new Date(),
4087	          })
4088	          .where(eq(companyMemberships.id, existing.id))
4089	          .returning()
4090	          .then((rows) => rows[0] ?? existing);
4091	      });
4092	      if (!updated) throw notFound("Member not found");
4093	
4094	      await logActivity(db, {
4095	        companyId,
4096	        actorType: "user",
4097	        actorId: req.actor.userId ?? "board",
4098	        action: "company_member.updated",
4099	        entityType: "company_membership",
4100	        entityId: memberId,
4101	        details: {
4102	          membershipRole: updated.membershipRole,
4103	          status: updated.status,
4104	        },
4105	      });
4106	
4107	      const member = (await loadCompanyMemberRecords(db, companyId)).find(
4108	        (entry) => entry.id === memberId,
4109	      );
4110	      if (!member) throw notFound("Member not found");
4111	      res.json(member);
4112	    }
4113	  );
